import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws_in = vals["Input"]
ws_out = wb["Output"] if "Output" in wb.sheetnames else wb.create_sheet("Output")

def is_blank(v):
    if v is None:
        return True
    if isinstance(v, str):
        return v.strip() == ""
    return False

def clean_value(v):
    if isinstance(v, str):
        v = v.strip()
        return v if v != "" else None
    return v

matches = []
for r in range(1, ws_in.max_row + 1):
    a = ws_in.cell(row=r, column=1).value
    b = ws_in.cell(row=r, column=2).value
    e = ws_in.cell(row=r, column=5).value

    if isinstance(e, str) and e.strip().lower() == "yes":
        if not is_blank(a) and not is_blank(b):
            matches.append(clean_value(b))

start_row, end_row = 11, 17
for i, r in enumerate(range(start_row, end_row + 1)):
    cell = ws_out.cell(row=r, column=2)
    if i < len(matches):
        cell.value = matches[i]
    else:
        cell.value = None

wb.save(OUT)

print("matches:", matches)
print("written:", [ws_out.cell(row=r, column=2).value for r in range(start_row, end_row + 1)])
